const { DataTypes } = require('sequelize');

/**
 * Generate a URL-friendly slug from a title.
 * - Lowercases the title
 * - Trims surrounding whitespace
 * - Replaces one or more whitespace characters with a single hyphen
 * - Strips any characters that are not lowercase alphanumeric or hyphen
 */
function generateSlug(title) {
  if (!title) return '';
  return String(title)
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '');
}

module.exports = (sequelize) => {
  const Article = sequelize.define(
    'Article',
    {
      title: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      slug: {
        type: DataTypes.STRING,
        allowNull: false,
      },
    },
    {
      tableName: 'Articles',
    }
  );

  // Hook: REDACTED-generate slug from title before validation runs.
  // `beforeValidate` fires for both `create` and `update`, and - when
  // `individualHooks: true` is passed to `bulkCreate` - for each row
  // being inserted in a bulk operation. This keeps a single source of
  // truth for slug generation that works for both single and bulk paths.
  Article.addHook('beforeValidate', (article) => {
    if (article.title && !article.slug) {
      article.slug = generateSlug(article.title);
    }
  });

  // Expose the slug helper so it can be reused (and so it is easy to
  // unit test in isolation if desired).
  Article.generateSlug = generateSlug;

  return Article;
};

